sys_script.script:
var gr = new GlideRecord('task');
gr.addQuery('active', true);
gr.query();
while (gr.next()) { gr.state = 3; gr.update(); }

while (task.next()) {
  var u = new GlideRecord('sys_user');
  u.addQuery('sys_id', task.assigned_to);
  u.query();
}

var r = new sn_ws.RESTMessageV2('Vendor', 'post');
var resp = r.execute();
gs.info(resp.getBody());

var gr = new GlideRecord('u_legacy_data');
gr.addQuery('u_code', code);
gr.deleteMultiple();

var n = 0;
while (kids.next()) { n++; }
return n;

var a = new GlideRecord('sysapproval_approver');
a.addQuery('document_id', current.sys_id);
a.setLimit(50);
a.query();
g_scratchpad.approvals = a.getRowCount();

var p = new GlideRecord('incident');
p.get(current.parent);
p.u_child_count = 1;
p.update();

sys_script_client.script:
function onLoad() {
  if (!g_user.hasRole('finance')) { g_form.setReadOnly('u_cost', true); }
}

function onChange(control, oldValue, newValue, isLoading) {
  if (isLoading) return;
  g_form.setMandatory('cause_notes', newValue == 'closed');
}

